<?php
//###################################################################################################################
//	weewx-Weather34 fork maintained by meisnick                                                                    #
//	Chart strings in the visitor's language. Replaces the static translations.js (generated by templateSetup.php  #
//	for the default language only) for w34highcharts/*-charts.html, which resolve every title and series name     #
//	through getTranslation(): exact phrases first, then word by word against the $lang keys.                       #
//###################################################################################################################
chdir(__DIR__ . '/..');
include_once 'w34_i18n.php';
header('Content-Type: application/javascript; charset=utf-8');
header('Cache-Control: private, max-age=0, must-revalidate');

// Chart titles, series names and menu items as plots.js passes them. Key = 'Hc' + the phrase's
// letters and digits (tools/i18n_keys.py derives the same keys).
$w34_chart_phrases = array(
    'Temperature Dewpoint Ranges & Averages', 'Temperature Dewpoint', 'Indoor Temperature Humidity Ranges & Averages',
    'Indoor Temperature Humidity', 'Temperature Dewpoint Humidity Ranges & Averages', 'Temperature Dewpoint Humidity',
    'HeatIndex/Windchill/Apparent Ranges & Averages', 'HeatIndex/Windchill/Apparent', 'Apparent/Temperature Ranges & Averages',
    'Apparent/Temperature', 'Dewpoint Ranges & Averages', 'Humidity Ranges & Averages', 'Barometer Ranges & Averages',
    'Barometer/Temp/Wind', 'Wind Speed Gust Max & Averages', 'Wind Speed Gust', 'Wind Gust and Direction with Barb',
    'Wind Direction Average', 'Wind Speed/Gust/Direction Max & Averages', 'Average Wind Speed/Gust/Direction',
    'Wind Speed/Gust/Direction', 'Monthly Rainfall', 'Strikes Count', 'Lightning Distance/Strikes/Energy Max & Avg/Cnt',
    'Lightning Strikes/Distance/Energy', 'Monthly Lightning Strikes', 'Solar Radiation Maximum & Average',
    'Solar Radiation/UV Index Max & Avg', 'Solar Radiation UV Index', 'UV Index Maximum & Average', 'Air Quality Maximum & Average',
    'Cloud Cover Max & Avg', 'Wind Rose', 'Frequency (%)',
    'Temperature Range', 'Average Temperature', 'Dewpoint Range', 'Average Dewpoint', 'Humidity Range', 'Average Humidity',
    'Temp Range', 'Average Temp', 'Windchill Range', 'Avg Windchill', 'Heatindex Range', 'Avg Heatindex', 'HeatIndex',
    'AppT Range', 'Avg AppT', 'Apparent Range', 'Average Apparent', 'Barometer Range', 'Average Barometer',
    'Wind Gust', 'Average Gust', 'Average Wind', 'Wind Speed', 'Wind Barb', 'Max Wind Gust', 'Average Wind Direction',
    'Avg Wind Speed', 'Avg Wind Gust', 'Avg Wind Direction', 'Wind Direction', 'RainFall', 'RainRate',
    'Distance Max', 'Distance Avg', 'Strikes Cnt', 'Energy Max', 'Energy Avg', 'Energy', 'Lightning Strikes',
    'Max Solar Radiation', 'Avg Solar Radiation', 'Solar Radiation Max', 'Solar Radiation Avg', 'UV Index Max', 'UV Index Avg',
    'UV Max', 'UV Avg', 'Cloud Cover Max', 'Cloud Cover Avg', 'Week', 'Month', 'Year', 'Lowest', 'Highest',
    'Select', 'View in full screen', 'Export Chart', 'Reload Chart', 'Auto Update Chart', 'Realtime Update', 'Radial Chart',
    'Hays Chart', 'Compare Dates', 'Scattered Clouds', 'Mostly Cloudy',
    'When mouse cursor turns to a hand then left click to drill down into chart data'
);

function w34_chart_key($phrase) {
    return 'Hc' . preg_replace('/[^A-Za-z0-9]/', '', ucwords(strtolower($phrase)));
}

$out = is_array($lang) ? $lang : array();
if (!w34_is_english()) {
    foreach ($w34_chart_phrases as $p) {
        $out[$p] = w34t(w34_chart_key($p), $p);
    }
    // single words and names plots.js passes that are not keys as written
    $more = array('Temperature' => 'Temperature', 'Dewpoint' => 'Dewpoint', 'Humidity' => 'Humidity', 'Barometer' => 'Barometer',
        'Temp' => 'Temp', 'Wind' => 'Wind', 'Feels' => 'Feelslike', 'Windchill' => 'Windchill', 'Apparent' => 'Apparent',
        'Rainfall' => 'Rainfall', 'Strikes' => 'Strikes', 'Distance' => 'Distance', 'Solar Radiation' => 'Solarradiation',
        'UV Index' => 'UvIndex', 'Air Quality' => 'AirQuality', 'Cloud Cover' => 'Cloudcover', 'Calm' => 'Calm',
        'Clear' => 'CondClear', 'Partly Cloudy' => 'CondPartlyCloudy', 'Overcast' => 'CondOvercast', 'All' => 'HcAll',
        'February' => 'Febuary', 'N' => 'DirN', 'E' => 'DirE', 'S' => 'DirS', 'W' => 'DirW', 'NNW' => 'DirNNW');
    foreach ($more as $p => $k) {
        $out[$p] = w34t($k, isset($out[$p]) ? $out[$p] : $p);
    }
}

// Highcharts' own text: month/day names in dates and axis labels, range-selector buttons and their titles
$months = array('January', 'Febuary', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December');
$monthsEn = array('January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December');
$days = array('Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday');
$w34_hc_locales = array('dk' => 'da-DK', 'nl' => 'nl-NL', 'pl' => 'pl-PL', 'dl' => 'de-DE', 'it' => 'it-IT', 'sp' => 'es-ES',
    'cat' => 'ca-ES', 'fr' => 'fr-FR', 'gr' => 'el-GR', 'tr' => 'tr-TR', 'hu' => 'hu-HU', 'no' => 'nb-NO', 'sw' => 'sv-SE');
$hcLang = null;
if (!w34_is_english()) {
    $hcLang = array(
        'months' => array_map(function ($k, $en) { return w34t($k, $en); }, $months, $monthsEn),
        'shortMonths' => array_map(function ($en) { return w34_datetext(substr($en, 0, 3)); }, $monthsEn),
        'weekdays' => array_map(function ($k) { return w34t($k, $k); }, $days),
        'shortWeekdays' => array_map(function ($k) { return w34_datetext(substr($k, 0, 3)); }, $days),
        'rangeSelector' => array(
            'allText' => w34t('HcAll', 'All'),
            'allTitle' => w34t('HcViewAll', 'View all'),
            'monthTitle' => w34t('HcViewMonths', 'View {count} months'),
            'yearTitle' => w34t('HcViewYears', 'View {count} years'),
            'ytdTitle' => w34t('HcViewYtd', 'View year to date'),
        ),
        'resetZoom' => w34t('Reset', 'Reset'),
        // %[ebY]-style formats (range-selector inputs) go through Intl with this locale; numbers keep the
        // dashboard's 1,234.5 style rather than the locale's
        'locale' => isset($w34_hc_locales[$lang_flag]) ? $w34_hc_locales[$lang_flag] : 'en-US',
        'decimalPoint' => '.',
        'thousandsSep' => ',',
        'loading' => w34t('HcLoading', 'Loading...'),
    );
}
echo 'var translations = ' . json_encode($out, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) . ";\n";
if ($hcLang) {
    echo 'if (window.Highcharts) Highcharts.setOptions({lang: ' . json_encode($hcLang, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) . "});\n";
}
